#include <bits/stdc++.h>
using namespace std;
using ll = long long;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    ll px[8], py[8];
    for (int i = 1; i <= 7; i++) cin >> px[i] >> py[i];

    auto sq = [](ll a) { return a * a; };

    bool ok = true;

    // Vectors P1->P2 and P1->P3
    ll ux = px[2] - px[1], uy = py[2] - py[1];
    ll vx = px[3] - px[1], vy = py[3] - py[1];

    // 1) Angle P2P1P3 acute (dot product strictly positive)
    ok = ok && (ux * vx + uy * vy > 0);

    // 2) |P1P2| == |P1P3|
    ok = ok && (sq(ux) + sq(uy) == sq(vx) + sq(vy));

    // Direction of line P2P3 (P2 != P3 guaranteed)
    ll dx = px[3] - px[2], dy = py[3] - py[2];

    // 3) P2, P3, P4, P5 collinear
    ll c4 = dx * (py[4] - py[2]) - dy * (px[4] - px[2]);
    ll c5 = dx * (py[5] - py[2]) - dy * (px[5] - px[2]);
    ok = ok && (c4 == 0 && c5 == 0);

    // 4) Midpoints of P2P3 and P4P5 coincide
    ok = ok && (px[2] + px[3] == px[4] + px[5] && py[2] + py[3] == py[4] + py[5]);

    // 5) |P2P3| > |P4P5|
    ok = ok && (sq(dx) + sq(dy) > sq(px[5] - px[4]) + sq(py[5] - py[4]));

    // 6) P4P6 and P5P7 perpendicular to P2P3
    ll ax = px[6] - px[4], ay = py[6] - py[4];
    ll bx = px[7] - px[5], by = py[7] - py[5];
    ok = ok && (ax * dx + ay * dy == 0);
    ok = ok && (bx * dx + by * dy == 0);

    // 7) |P4P6| == |P5P7|
    ok = ok && (sq(ax) + sq(ay) == sq(bx) + sq(by));

    // 8) P1 and P6 on strictly opposite sides of the line through P2P3
    ll s1 = dx * (py[1] - py[2]) - dy * (px[1] - px[2]);
    ll s6 = dx * (py[6] - py[2]) - dy * (px[6] - px[2]);
    ok = ok && ((s1 > 0 && s6 < 0) || (s1 < 0 && s6 > 0));

    cout << (ok ? 'S' : 'N') << '\n';
    return 0;
}
